export async function seedProductionContactsIfNeeded() {
  const rows = await db.select({ id: contactsTable.id }).from(contactsTable);
  if (rows.length >= DEV_CONTACTS.length) {
    console.log(`Contacts already synced (${rows.length} rows). Skipping.`);
    return;
  }

  console.log(`Syncing contacts to production (${rows.length} existing, ${DEV_CONTACTS.length} total)...`);

  const [validRoleIds, validIndustryIds, validCompanyIds] = await Promise.all([
    db.select({ id: rolesTable.id }).from(rolesTable).then(rs => new Set(rs.map(r => r.id))),
    db.select({ id: industriesTable.id }).from(industriesTable).then(rs => new Set(rs.map(r => r.id))),
    db.select({ id: companiesTable.id }).from(companiesTable).then(rs => new Set(rs.map(r => r.id))),
  ]);

  const fk = (v: unknown, s: Set<number>) => {
    const n = parseInt(String(v ?? ""));
    return !isNaN(n) && s.has(n) ? n : null;
  };

  let inserted = 0, skipped = 0;
  for (const c of DEV_CONTACTS) {
    try {
      const email = c.email || null;
      if (email) {
        const dup = await db.select({ id: contactsTable.id }).from(contactsTable)
          .where(eq(contactsTable.email, email)).limit(1);
        if (dup.length > 0) { skipped++; continue; }
      }
      await db.insert(contactsTable).values({
        firstName:     c.first_name,
        lastName:      c.last_name,
        roleId:        fk(c.role_id, validRoleIds),
        industryId:    fk(c.industry_id, validIndustryIds),
        companyId:     fk(c.company_id, validCompanyIds),
        jobTitle:      c.job_title  || null,
        department:    c.department || null,
        seniority:     c.seniority  || null,
        email,
        phone:         c.phone         || null,
        location:      c.location      || null,
        country:       c.country       || null,
        linkedinUrl:   c.linkedin_url  || null,
        twitterHandle: c.twitter_handle || null,
        bio:           c.bio           || null,
      });
      inserted++;
    } catch { skipped++; }
  }
  console.log(`Contacts sync complete: ${inserted} inserted, ${skipped} skipped.`);
}
